package com.library.controller; import com.library.common.annotation.RequireRole; import com.library.common.constant.RoleConstant; import com.library.common.model.*; import com.library.model.dto.*; import com.library.model.vo.BorrowVO; import com.library.service.BorrowService; import com.library.util.UserContext; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/borrows") public class BorrowController {private final BorrowService service;public BorrowController(BorrowService service){this.service=service;} @PostMapping @RequireRole({RoleConstant.ADMIN,RoleConstant.READER}) public ApiResult<Void> borrow(@Valid @RequestBody BorrowDTO x){service.borrow(x);return ApiResult.success();} @PutMapping("/return") @RequireRole({RoleConstant.ADMIN,RoleConstant.READER}) public ApiResult<Void> returnBook(@Valid @RequestBody ReturnDTO x){service.returnBook(x);return ApiResult.success();} @GetMapping public ApiResult<PageResult<BorrowVO>> page(@RequestParam(required=false) Long readerId,@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="10") int size){Long id=RoleConstant.READER.equals(UserContext.get().getRole())?UserContext.get().getId():readerId;return ApiResult.success(service.page(id,page,size));} @GetMapping("/timeline") @RequireRole({RoleConstant.ADMIN,RoleConstant.READER}) public ApiResult<List<BorrowVO>> timeline(@RequestParam(required=false) Long readerId){Long id=RoleConstant.READER.equals(UserContext.get().getRole())?UserContext.get().getId():readerId;return ApiResult.success(service.timeline(id));} }
